func CreatePageviews(ctx context.Context, exec storage.Executor, websiteID uuid.UUID, count int, opts ...PageviewOption) ([]models.PageviewEntity, error) {
	pageviews := make([]models.PageviewEntity, 0, count)

	for i := 0; i < count; i++ {
		entity, err := CreatePageview(ctx, exec, websiteID, opts...)
		if err != nil {
			return nil, fmt.Errorf("failed to create pageview %d: %w", i+1, err)
		}
		pageviews = append(pageviews, entity)
	}

	return pageviews, nil
}

